/**
 * Notifications Table Schema
 *
 * Stores warning and error notifications generated by formula fields.
 * Info-level notifications are not persisted to this table.
 *
 * @module notifications-schema
 */

import { sql } from "drizzle-orm";
import {
  pgTable,
  varchar,
  text,
  timestamp,
  index,
  jsonb,
} from "drizzle-orm/pg-core";
import { nanoid } from "@zdocs/util";
import { organizationsTbl } from "./organizations";
import { documentTbl } from "./documents";
import {
  NOTIFICATION_STATUSES,
  NOTIFICATION_LEVELS,
  NOTIFICATION_TYPES,
  type NotificationRecord,
} from "@zdocs/types";

export const notificationsTbl = pgTable(
  "notifications",
  {
    id: varchar("id", { length: 191 })
      .primaryKey()
      .$defaultFn(() => nanoid()),

    orgId: varchar("org_id", { length: 191 })
      .notNull()
      .references(() => organizationsTbl.id, { onDelete: "cascade" }),

    documentId: varchar("document_id", { length: 191 })
      .references(() => documentTbl.id, { onDelete: "cascade" }), // Nullable for task-scoped notifications

    // Notification type/scope
    notificationType: text("notification_type", { enum: NOTIFICATION_TYPES })
      .notNull()
      .default("DOCUMENT"),

    // Metadata for flexible linking (e.g., taskId for TASK notifications)
    metadata: jsonb("metadata").$type<Record<string, unknown> | null>(),

    // Notification content
    level: text("level", { enum: NOTIFICATION_LEVELS }).notNull(),
    message: text("message").notNull(),
    fieldPath: text("field_path"), // e.g., "header.total", "items[2].amount"
    formulaField: text("formula_field"), // Which formula field generated this

    // Status workflow
    status: text("status", { enum: NOTIFICATION_STATUSES })
      .notNull()
      .default("NEW"),

    // Timestamps
    createdAt: timestamp("created_at", { mode: "date" })
      .notNull()
      .default(sql`now()`),
  },
  (table) => ({
    // Query by org + status (for notification badge/list)
    orgStatusIdx: index("notification_org_status_idx").on(
      table.orgId,
      table.status
    ),

    // Query by document (for document detail view) - only indexes non-null documentId
    documentIdx: index("notification_document_idx").on(
      table.orgId,
      table.documentId
    ).where(sql`document_id IS NOT NULL`),

    // Query by notification type
    notificationTypeIdx: index("notification_type_idx").on(
      table.orgId,
      table.notificationType,
      table.status
    ),

    // Query active notifications (NEW or PENDING)
    activeIdx: index("notification_active_idx")
      .on(table.orgId, table.createdAt)
      .where(sql`status IN ('NEW', 'PENDING')`),
  })
);

// Type compatibility check (will error at build time if incompatible)
const _typeCheck: NotificationRecord = {} as typeof notificationsTbl.$inferSelect;

